function decodeEntities(s) {
  return s
    .replace(/&nbsp;|&#160;|&#xa0;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/ /g, ' ');
}

function extractText(payload) {
  if (payload?.body?.data) {
    const text = Buffer.from(payload.body.data, 'base64url').toString('utf-8');
    if (text.trim()) return text;
  }
  function searchParts(parts = []) {
    for (const part of parts) {
      if (part.mimeType === 'text/plain' && part.body?.data)
        return Buffer.from(part.body.data, 'base64url').toString('utf-8');
      if (part.parts) {
        const found = searchParts(part.parts);
        if (found) return found;
      }
    }
    for (const part of parts) {
      if (part.mimeType === 'text/html' && part.body?.data) {
        const html = Buffer.from(part.body.data, 'base64url').toString('utf-8');
        return html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
      }
    }
    return null;
  }
  return searchParts(payload?.parts) || '';
}

const msg = $input.first().json;
const headers = msg.payload?.headers || [];
const subject = headers.find(h => h.name.toLowerCase() === 'subject')?.value || '';
const text = decodeEntities(extractText(msg.payload)).replace(/[﻿​]/g, '').replace(/\s+/g, ' ');

const trackingRef = text.match(/N° du colis\s*([A-Z0-9]{8,20})/i)?.[1];

// Etape deduite du sujet en priorite, puis du titre dans le corps.
let status = null;
if (/confirmation de la livraison/i.test(subject)) status = 'delivered';
else if (/en route/i.test(subject)) status = 'in_transit';
else if (/d[eé]pos[eé]/i.test(subject)) status = 'deposited';
else if (/Colis livr[eé]/i.test(text)) status = 'delivered';
else if (/En transit/.test(text)) status = 'in_transit';
else if (/Confirmation d[eé]p[oô]t/i.test(text)) status = 'deposited';

if (!trackingRef || !status) {
  console.log('Mail Colissimo ignore', { subject, trackingRef, status });
  return [];
}

// Date prevue seule (ex. "jeudi 15 octobre") : l'appli ajoute elle-meme "Livraison prevue".
const eta = text.match(/Il sera livr[eé]\s+(.+?)\s+Suivre/i)?.[1] || null;

return [{ json: { trackingRef, status, detail: status === 'delivered' ? null : eta } }];
